create or replace function public.next_reference(p_prefix text,p_scope text default 'GLOBAL') returns text language plpgsql security definer set search_path=public as $$
declare k text:=upper(p_prefix)||':'||upper(p_scope)||':'||to_char(current_date,'YY')||to_char(current_date+interval '1 year','YY');n bigint;
begin insert into document_sequences(sequence_key,current_value) values(k,1) on conflict(sequence_key) do update set current_value=document_sequences.current_value+1,updated_at=now() returning current_value into n;return upper(p_prefix)||'-'||upper(p_scope)||'-'||to_char(current_date,'YY')||to_char(current_date+interval '1 year','YY')||'-'||lpad(n::text,6,'0');end$$;
create or replace function public.uom_to_kg(p_qty numeric,p_uom text) returns numeric language sql immutable as $$select case upper(p_uom) when 'KG' then p_qty when 'QTL' then p_qty*100 when 'MT' then p_qty*1000 else null end$$;
create or replace function public.current_rule_snapshot(p_commodity_id uuid) returns jsonb language sql stable as $$select to_jsonb(c) from commodities c where c.id=p_commodity_id$$;
create or replace function public.calculate_transaction_quantities(p_commodity_id uuid,p_direction text,p_entered_qty numeric,p_uom text,p_bags numeric) returns table(inventory_qty_kg numeric,commercial_qty_kg numeric,bag_weight_effect_kg numeric) language plpgsql stable as $$
declare c commodities%rowtype;entered_kg numeric;basis weight_basis;
begin select * into c from commodities where id=p_commodity_id and is_active;if not found then raise exception 'Commodity not found';end if;entered_kg:=uom_to_kg(p_entered_qty,p_uom);basis:=case when p_direction='inward' then c.inward_weight_basis else c.outward_weight_basis end;commercial_qty_kg:=entered_kg;if c.inventory_quantity_basis='inclusive_of_bag' then inventory_qty_kg:=entered_kg;bag_weight_effect_kg:=0;elsif basis='inclusive_of_bag' then inventory_qty_kg:=entered_kg-coalesce(p_bags,0)*c.standard_empty_bag_tare_kg;bag_weight_effect_kg:=entered_kg-inventory_qty_kg;else inventory_qty_kg:=entered_kg;bag_weight_effect_kg:=0;end if;if inventory_qty_kg<0 then raise exception 'Bag tare exceeds entered quantity';end if;return next;end$$;
create or replace function public.check_period_open(p_date date,p_godown_id uuid) returns void language plpgsql stable as $$declare g godowns%rowtype;locked boolean;begin select * into g from godowns where id=p_godown_id;select exists(select 1 from period_closings p where p.status='closed' and p_date between p.period_start and p.period_end and (p.state_code is null or p.state_code=g.state_code) and (p.gstin is null or p.gstin=g.gstin)) into locked;if locked then raise exception 'Inventory period is closed';end if;end$$;
create or replace function public.lot_balance(p_lot_id uuid,p_as_on date default current_date) returns numeric language sql stable as $$select coalesce(sum(quantity_kg),0) from stock_ledger_entries where lot_id=p_lot_id and entry_date<=p_as_on$$;
create or replace function public.lot_controlled_qty(p_lot_id uuid,p_type text default null) returns numeric language sql stable as $$select coalesce(sum(quantity_kg),0) from stock_controls where lot_id=p_lot_id and status='active' and (p_type is null or control_type=p_type)$$;
create or replace function public.consume_fifo(p_tx uuid,p_lot uuid,p_qty numeric) returns numeric language plpgsql security definer set search_path=public as $$declare remain numeric:=p_qty;r fifo_layers%rowtype;take numeric;cost numeric:=0;begin for r in select * from fifo_layers where lot_id=p_lot and remaining_qty_kg>0 order by layer_date,id for update loop exit when remain<=0;take:=least(remain,r.remaining_qty_kg);update fifo_layers set remaining_qty_kg=remaining_qty_kg-take where id=r.id;insert into fifo_consumptions(outward_transaction_id,fifo_layer_id,quantity_kg,cost_value) values(p_tx,r.id,take,take*r.cost_per_kg);cost:=cost+take*r.cost_per_kg;remain:=remain-take;end loop;if remain>0.000001 then raise exception 'Insufficient FIFO quantity';end if;return round(cost,2);end$$;
create or replace function public.create_inward_draft(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare tx inventory_transactions;ref text;g godowns%rowtype;c commodities%rowtype;q record;begin select * into g from godowns where id=(p_payload->>'godown_id')::uuid;perform check_period_open(current_date,g.id);select * into c from commodities where id=(p_payload->>'commodity_id')::uuid;select * into q from calculate_transaction_quantities(c.id,'inward',(p_payload->>'entered_qty')::numeric,p_payload->>'uom',coalesce((p_payload->>'bags')::numeric,0));ref:=next_reference('INW',g.state_code||'-'||g.code);insert into inventory_transactions(reference_no,transaction_type,subtype,status,maker_user_id,remarks,source_reference,commercial_value,metadata) values(ref,'inward',p_payload->>'subtype','pending_approval',auth.uid(),p_payload->>'remarks',p_payload->>'source_reference',q.inventory_qty_kg*coalesce((p_payload->>'rate_per_mt')::numeric,0)/1000,p_payload||jsonb_build_object('inventory_qty_kg',q.inventory_qty_kg,'commercial_qty_kg',q.commercial_qty_kg,'bag_weight_effect_kg',q.bag_weight_effect_kg,'commodity_rule_snapshot',current_rule_snapshot(c.id))) returning * into tx;return jsonb_build_object('id',tx.id,'reference_no',ref);end$$;
create or replace function public.create_outward_draft(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare tx inventory_transactions;ref text;l lots%rowtype;g godowns%rowtype;q record;begin select * into l from lots where id=(p_payload->>'lot_id')::uuid;select * into g from godowns where id=l.godown_id;perform check_period_open(current_date,g.id);select * into q from calculate_transaction_quantities(l.commodity_id,'outward',(p_payload->>'entered_qty')::numeric,p_payload->>'uom',coalesce((p_payload->>'bags')::numeric,0));ref:=next_reference('OUT',g.state_code||'-'||g.code);insert into inventory_transactions(reference_no,transaction_type,subtype,status,maker_user_id,remarks,tally_invoice_no,commercial_value,metadata) values(ref,'outward','sales','pending_approval',auth.uid(),p_payload->>'remarks',p_payload->>'tally_invoice_no',q.commercial_qty_kg*coalesce((p_payload->>'sale_rate_per_mt')::numeric,0)/1000,p_payload||jsonb_build_object('inventory_qty_kg',q.inventory_qty_kg,'commercial_qty_kg',q.commercial_qty_kg,'bag_weight_effect_kg',q.bag_weight_effect_kg)) returning * into tx;return jsonb_build_object('id',tx.id,'reference_no',ref);end$$;
create or replace function public.create_transfer_draft(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare tx inventory_transactions;ref text;l lots%rowtype;g godowns%rowtype;qty numeric;begin select * into l from lots where id=(p_payload->>'lot_id')::uuid;select * into g from godowns where id=l.godown_id;perform check_period_open(current_date,g.id);qty:=uom_to_kg((p_payload->>'entered_qty')::numeric,p_payload->>'uom');ref:=next_reference('TRF',g.state_code||'-'||g.code);insert into inventory_transactions(reference_no,transaction_type,subtype,status,maker_user_id,remarks,metadata) values(ref,'internal_transfer','godown_transfer','pending_approval',auth.uid(),p_payload->>'remarks',p_payload||jsonb_build_object('inventory_qty_kg',qty)) returning * into tx;return jsonb_build_object('id',tx.id,'reference_no',ref);end$$;
create or replace function public.create_return_draft(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare tx inventory_transactions;ref text;g godowns%rowtype;qty numeric;begin select * into g from godowns where id=(p_payload->>'destination_godown_id')::uuid;qty:=uom_to_kg((p_payload->>'entered_qty')::numeric,p_payload->>'uom');ref:=next_reference(case when p_payload->>'return_type'='customer_return' then 'SRT' else 'PRT' end,g.state_code||'-'||g.code);insert into inventory_transactions(reference_no,transaction_type,subtype,status,maker_user_id,remarks,source_reference,metadata) values(ref,'return',p_payload->>'return_type','pending_approval',auth.uid(),p_payload->>'remarks',p_payload->>'original_reference',p_payload||jsonb_build_object('inventory_qty_kg',qty)) returning * into tx;return jsonb_build_object('id',tx.id,'reference_no',ref);end$$;
create or replace function public.approve_and_post_transaction(p_transaction_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare tx inventory_transactions;p jsonb;l lots%rowtype;new_lot lots%rowtype;qty numeric;bags numeric;cost numeric;ref text;free_qty numeric;begin select * into tx from inventory_transactions where id=p_transaction_id for update;if tx.status<>'pending_approval' then raise exception 'Transaction is not pending approval';end if;if tx.maker_user_id=auth.uid() then raise exception 'Maker cannot approve own transaction';end if;if not exists(select 1 from profiles where id=auth.uid() and is_active and role_code in('administrator','approver','stock_accountant','warehouse_supervisor')) then raise exception 'User cannot approve';end if;p:=tx.metadata;qty:=(p->>'inventory_qty_kg')::numeric;bags:=coalesce((p->>'bags')::numeric,0);
if tx.transaction_type='inward' then ref:=next_reference('LOT',(select code from commodities where id=(p->>'commodity_id')::uuid));insert into lots(lot_no,commodity_id,crop_year_id,quality_mark_id,owner_type,owner_party_id,godown_id,form,source_lineage,commodity_rule_snapshot,created_by_transaction_id) values(ref,(p->>'commodity_id')::uuid,nullif(p->>'crop_year_id','')::uuid,nullif(p->>'quality_mark_id','')::uuid,case when tx.subtype='storage' then 'storage'::ownership_type else 'own'::ownership_type end,nullif(p->>'party_id','')::uuid,(p->>'godown_id')::uuid,case when (p->'commodity_rule_snapshot'->>'inward_packing_mode')='loose' then 'loose'::packing_mode else 'bags'::packing_mode end,jsonb_build_array(jsonb_build_object('party_id',p->>'party_id','reference',tx.source_reference,'qty_kg',qty)),p->'commodity_rule_snapshot',tx.id) returning * into new_lot;cost:=round(qty*coalesce((p->>'rate_per_mt')::numeric,0)/1000,2);insert into stock_ledger_entries(transaction_id,entry_no,lot_id,entry_date,entry_type,quantity_kg,bags,commercial_quantity_kg,cost_value,bag_weight_effect_kg,godown_id) values(tx.id,1,new_lot.id,tx.transaction_date,'INWARD_IN',qty,bags,(p->>'commercial_qty_kg')::numeric,cost,(p->>'bag_weight_effect_kg')::numeric,new_lot.godown_id);insert into fifo_layers(lot_id,source_transaction_id,layer_date,original_qty_kg,remaining_qty_kg,cost_per_kg,original_value) values(new_lot.id,tx.id,tx.transaction_date,qty,qty,case when qty=0 then 0 else cost/qty end,cost);
elsif tx.transaction_type='outward' then select * into l from lots where id=(p->>'lot_id')::uuid for update;free_qty:=lot_balance(l.id)-lot_controlled_qty(l.id,'block')-lot_controlled_qty(l.id,'damage')-lot_controlled_qty(l.id,'pledge');if free_qty<qty then raise exception 'Insufficient released/free stock';end if;cost:=consume_fifo(tx.id,l.id,qty);insert into stock_ledger_entries(transaction_id,entry_no,lot_id,entry_date,entry_type,quantity_kg,bags,commercial_quantity_kg,cost_value,bag_weight_effect_kg,godown_id) values(tx.id,1,l.id,tx.transaction_date,'OUTWARD_OUT',-qty,-bags,-(p->>'commercial_qty_kg')::numeric,-cost,(p->>'bag_weight_effect_kg')::numeric,l.godown_id);
elsif tx.transaction_type='internal_transfer' then select * into l from lots where id=(p->>'lot_id')::uuid for update;free_qty:=lot_balance(l.id)-lot_controlled_qty(l.id,null);if free_qty<qty then raise exception 'Insufficient free stock';end if;ref:=next_reference('LOT',(select code from commodities where id=l.commodity_id));insert into lots(lot_no,commodity_id,crop_year_id,quality_mark_id,owner_type,owner_party_id,godown_id,form,parent_lot_ids,source_lineage,commodity_rule_snapshot,created_by_transaction_id) values(ref,l.commodity_id,l.crop_year_id,l.quality_mark_id,l.owner_type,l.owner_party_id,(p->>'destination_godown_id')::uuid,l.form,array[l.id],l.source_lineage,l.commodity_rule_snapshot,tx.id) returning * into new_lot;cost:=consume_fifo(tx.id,l.id,qty);insert into stock_ledger_entries(transaction_id,entry_no,lot_id,entry_date,entry_type,quantity_kg,bags,commercial_quantity_kg,cost_value,godown_id) values(tx.id,1,l.id,tx.transaction_date,'TRANSFER_OUT',-qty,-bags,-qty,-cost,l.godown_id),(tx.id,2,new_lot.id,tx.transaction_date,'TRANSFER_IN',qty,bags,qty,cost,new_lot.godown_id);insert into fifo_layers(lot_id,source_transaction_id,layer_date,original_qty_kg,remaining_qty_kg,cost_per_kg,original_value) values(new_lot.id,tx.id,tx.transaction_date,qty,qty,case when qty=0 then 0 else cost/qty end,cost);
elsif tx.transaction_type='return' then select * into l from lots where id=(p->>'lot_id')::uuid;if tx.subtype='customer_return' then ref:=next_reference('RETLOT',(select code from commodities where id=l.commodity_id));insert into lots(lot_no,commodity_id,crop_year_id,quality_mark_id,owner_type,owner_party_id,godown_id,form,parent_lot_ids,source_lineage,commodity_rule_snapshot,created_by_transaction_id,status) values(ref,l.commodity_id,l.crop_year_id,l.quality_mark_id,l.owner_type,l.owner_party_id,(p->>'destination_godown_id')::uuid,l.form,array[l.id],l.source_lineage,l.commodity_rule_snapshot,tx.id,'under_inspection') returning * into new_lot;insert into stock_ledger_entries(transaction_id,entry_no,lot_id,entry_date,entry_type,quantity_kg,bags,commercial_quantity_kg,cost_value,godown_id) values(tx.id,1,new_lot.id,tx.transaction_date,'CUSTOMER_RETURN_IN',qty,bags,qty,0,new_lot.godown_id);insert into fifo_layers(lot_id,source_transaction_id,layer_date,original_qty_kg,remaining_qty_kg,cost_per_kg,original_value) values(new_lot.id,tx.id,tx.transaction_date,qty,qty,0,0);else if lot_balance(l.id)<qty then raise exception 'Insufficient stock';end if;cost:=consume_fifo(tx.id,l.id,qty);insert into stock_ledger_entries(transaction_id,entry_no,lot_id,entry_date,entry_type,quantity_kg,bags,commercial_quantity_kg,cost_value,godown_id) values(tx.id,1,l.id,tx.transaction_date,'SUPPLIER_RETURN_OUT',-qty,-bags,-qty,-cost,l.godown_id);end if;else raise exception 'Unsupported transaction type';end if;
update inventory_transactions set status='posted',approver_user_id=auth.uid(),approved_at=now(),posted_at=now() where id=tx.id;insert into audit_events(user_id,action,entity_type,entity_id,details) values(auth.uid(),'approve_and_post','inventory_transaction',tx.id,jsonb_build_object('reference',tx.reference_no));return jsonb_build_object('reference_no',tx.reference_no,'status','posted');end$$;
create or replace view public.v_lot_available as select l.id lot_id,l.lot_no,c.name commodity_name,g.full_name godown_name,l.godown_id,l.commodity_id,l.crop_year_id,l.quality_mark_id,coalesce(sum(e.quantity_kg),0) book_qty_kg,coalesce(sum(e.bags),0) bags,coalesce(sum(e.quantity_kg),0)-coalesce((select sum(sc.quantity_kg) from stock_controls sc where sc.lot_id=l.id and sc.status='active' and sc.control_type in('block','damage','pledge','sales_reservation')),0) available_qty_kg from lots l join commodities c on c.id=l.commodity_id join godowns g on g.id=l.godown_id left join stock_ledger_entries e on e.lot_id=l.id group by l.id,c.name,g.full_name;
create or replace function public.stock_as_on_date(p_as_on date default current_date) returns table(commodity_id uuid,commodity_name text,stock_qty_kg numeric,bags numeric,to_be_delivered_qty_kg numeric,saleable_qty_kg numeric,pledged_qty_kg numeric,released_not_dispatched_qty_kg numeric,free_physical_qty_kg numeric,blocked_qty_kg numeric,fifo_value numeric,bag_weight_effect_kg numeric) language sql stable as $$with stock as(select l.commodity_id,sum(e.quantity_kg) qty,sum(e.bags) bags,sum(e.bag_weight_effect_kg) bag_effect from stock_ledger_entries e join lots l on l.id=e.lot_id where e.entry_date<=p_as_on and l.owner_type='own' group by l.commodity_id),orders as(select commodity_id,sum(greatest(order_qty_kg-cancelled_qty_kg-coalesce((select abs(sum(e.quantity_kg)) from stock_ledger_entries e where e.sales_order_id=so.id and e.entry_type='OUTWARD_OUT' and e.entry_date<=p_as_on),0),0)) due from sales_orders so where status='open' group by commodity_id),ctrl as(select l.commodity_id,sum(sc.quantity_kg) filter(where sc.control_type='pledge' and sc.status='active') pledged,sum(sc.quantity_kg) filter(where sc.control_type in('block','damage') and sc.status='active') blocked from stock_controls sc join lots l on l.id=sc.lot_id group by l.commodity_id),val as(select l.commodity_id,sum(f.remaining_qty_kg*f.cost_per_kg) value from fifo_layers f join lots l on l.id=f.lot_id where f.layer_date<=p_as_on group by l.commodity_id) select c.id,c.name,coalesce(s.qty,0),coalesce(s.bags,0),coalesce(o.due,0),greatest(coalesce(s.qty,0)-coalesce(o.due,0)-coalesce(ctrl.blocked,0),0),coalesce(ctrl.pledged,0),0,greatest(coalesce(s.qty,0)-coalesce(ctrl.pledged,0)-coalesce(ctrl.blocked,0),0),coalesce(ctrl.blocked,0),coalesce(v.value,0),coalesce(s.bag_effect,0) from commodities c left join stock s on s.commodity_id=c.id left join orders o on o.commodity_id=c.id left join ctrl on ctrl.commodity_id=c.id left join val v on v.commodity_id=c.id where c.is_active and coalesce(s.qty,0)<>0 order by c.name$$;
create or replace view public.v_inventory_analytics as select s.*,case when s.stock_qty_kg=0 then 0 else s.fifo_value/s.stock_qty_kg*1000 end average_cost_per_mt,(select min(layer_date) from fifo_layers f join lots l on l.id=f.lot_id where l.commodity_id=s.commodity_id and f.remaining_qty_kg>0) oldest_fifo_date from stock_as_on_date(current_date) s;
create or replace view public.v_bank_pledge_stock as select b.name bank,cm.name collateral_manager,g.state,g.full_name godown,c.name commodity,cy.name crop_year,q.name quality,l.lot_no,lot_balance(l.id) physical_stock_kg,pl.pledged_qty_kg-pl.released_qty_kg pledged_stock_kg,pl.released_qty_kg released_stock_kg,lot_balance(l.id)-(pl.pledged_qty_kg-pl.released_qty_kg) free_stock_kg,p.bank_value,p.funding_done,p.due_date,p.status from pledge_lots pl join bank_pledges p on p.id=pl.pledge_id join banks b on b.id=p.bank_id left join collateral_managers cm on cm.id=p.collateral_manager_id join lots l on l.id=pl.lot_id join commodities c on c.id=l.commodity_id left join crop_years cy on cy.id=l.crop_year_id left join quality_marks q on q.id=l.quality_mark_id join godowns g on g.id=l.godown_id;
create or replace function public.close_period(p_start date,p_end date,p_state_code text default null,p_gstin text default null) returns uuid language plpgsql security definer set search_path=public as $$declare id uuid;begin if exists(select 1 from inventory_transactions where status='pending_approval' and transaction_date between p_start and p_end) then raise exception 'Pending approvals exist in period';end if;insert into period_closings(period_start,period_end,state_code,gstin,status,closed_by,closed_at) values(p_start,p_end,p_state_code,p_gstin,'closed',auth.uid(),now()) returning period_closings.id into id;return id;end$$;
grant execute on function create_inward_draft(jsonb),create_outward_draft(jsonb),create_transfer_draft(jsonb),create_return_draft(jsonb),approve_and_post_transaction(uuid),stock_as_on_date(date),close_period(date,date,text,text) to authenticated;
